            "118E6 118EF 1D20C 1D416 1D430 1D44A 1D464 1D47E 1D498 1D4B2 1D4CC 1D4E6 1D500 1D51A 1D534 1D54E " +
            "1D568 1D582 1D59C 1D5B6 1D5D0 1D5EA 1D604 1D61E 1D638 1D652 1D66C 1D686 1D6A0",
    )

    private val LETTERS: Map<Int, Char> = HashMap<Int, Char>().apply {
        for ((letter, codePoints) in TABLE) for (hex in codePoints.split(' ')) put(hex.toInt(16), letter)
    }

    /** The letter [codePoint] looks like, or null when it looks like none of them. */
    fun letterOf(codePoint: Int): Char? = LETTERS[codePoint]

    /** How many code points the table holds, for its test. */
    val size: Int get() = LETTERS.size
}
